import re,struct,hashlib,json,os
U='/tmp/claude-0/-home-user-ECDEV/c000280f-3151-5564-9330-dca84c370647/scratchpad/urlwork/ucd/'
OUT='domain/commerce/idna-tables/'
def w(name,vals):
    open(OUT+name,'wb').write(struct.pack('<%dI'%len(vals),*vals))
def rng(s):
    a,_,b=s.partition('..'); return int(a,16),int(b or a,16)
ST={'valid':0,'ignored':1,'mapped':2,'deviation':3,'disallowed':4,'disallowed_STD3_valid':5,'disallowed_STD3_mapped':6}
rows=[];pool=[]
for l in open(U+'idna-latest.txt',encoding='utf-8'):
    l=l.split('#')[0].strip()
    if not l: continue
    f=[x.strip() for x in l.split(';')]
    a,b=rng(f[0]); st=ST[f[1]]
    mp=[int(x,16) for x in f[2].split()] if len(f)>2 and f[2] and not re.match(r'^(NV8|XV8)',f[2]) else []
    off=len(pool); pool+=mp
    rows.append((a,b,st,off,len(mp)))
rows.sort()
merged=[]
for r in rows:
    if merged and r[2] not in(2,3,6) and merged[-1][2]==r[2] and merged[-1][4]==0 and merged[-1][1]+1==r[0] and r[4]==0:
        merged[-1]=(merged[-1][0],r[1],r[2],0,0)
    else: merged.append(r)
flat=[]
for a,b,st,off,n in merged: flat+=[a,b,(st<<24)|n,off]
w('idna-ranges.bin',flat); w('idna-map.bin',pool)
print('idna ranges',len(merged),'pool',len(pool))
gc={};ccc={};decomp={};first=None
for l in open(U+'UnicodeData.txt',encoding='utf-8'):
    f=l.rstrip('\n').split(';')
    cp=int(f[0],16); name=f[1]
    if name.endswith(', First>'): first=cp; continue
    r=range(first,cp+1) if name.endswith(', Last>') else [cp]
    first=None
    for c in r:
        gc[c]=f[2]
        if f[3]!='0': ccc[c]=int(f[3])
    if f[5] and not f[5].startswith('<'): decomp[cp]=[int(x,16) for x in f[5].split()]
def ranges_of(pred,universe):
    out=[];start=prev=None
    for c in sorted(universe):
        if pred(c):
            if start is None: start=prev=c
            elif c==prev+1: prev=c
            else: out.append((start,prev)); start=prev=c
    if start is not None: out.append((start,prev))
    return out
marks=ranges_of(lambda c:gc[c][0]=='M',gc.keys())
w('marks.bin',[x for r in marks for x in r])
cr=[]
for c in sorted(ccc):
    if cr and cr[-1][1]+1==c and cr[-1][2]==ccc[c]: cr[-1]=(cr[-1][0],c,ccc[c])
    else: cr.append((c,c,ccc[c]))
w('ccc.bin',[x for r in cr for x in r])
def full(c):
    if c in decomp:
        out=[]
        for d in decomp[c]: out+=full(d)
        return out
    return [c]
fd={c:full(c) for c in decomp}
dflat=[];dpool=[]
for c in sorted(fd):
    dflat+=[c,len(dpool),len(fd[c])]; dpool+=fd[c]
w('nfd.bin',dflat); w('nfd-pool.bin',dpool)
excl=set()
for l in open(U+'DerivedNormalizationProps.txt',encoding='utf-8'):
    l=l.split('#')[0].strip()
    if not l: continue
    f=[x.strip() for x in l.split(';')]
    if f[1]=='Full_Composition_Exclusion':
        a,b=rng(f[0]); excl.update(range(a,b+1))
pairs=sorted((d[0],d[1],c) for c,d in decomp.items() if len(d)==2 and c not in excl)
w('compose.bin',[x for p in pairs for x in p])
print('nfd',len(fd),'compose',len(pairs),'ccc ranges',len(cr),'marks',len(marks))
BC=['L','R','AL','EN','ES','ET','AN','CS','NSM','BN','B','S','WS','ON','LRE','LRO','RLE','RLO','PDF','LRI','RLI','FSI','PDI']
bidi=[0]*0x110000
for l in open(U+'DerivedBidiClass.txt',encoding='utf-8'):
    m=re.match(r'#\s*@missing:\s*([0-9A-F]+)\.\.([0-9A-F]+);\s*(\w+)',l)
    if m:
        name=m[3]; v=BC.index({'Left_To_Right':'L','Right_To_Left':'R','Arabic_Letter':'AL','European_Terminator':'ET','Boundary_Neutral':'BN'}.get(name,name))
        for c in range(int(m[1],16),int(m[2],16)+1): bidi[c]=v
for l in open(U+'DerivedBidiClass.txt',encoding='utf-8'):
    l=l.split('#')[0].strip()
    if not l: continue
    f=[x.strip() for x in l.split(';')]
    a,b=rng(f[0]); v=BC.index(f[1])
    for c in range(a,b+1): bidi[c]=v
br=[]
for c,v in enumerate(bidi):
    if v==0: continue
    if br and br[-1][1]+1==c and br[-1][2]==v: br[-1]=(br[-1][0],c,v)
    else: br.append((c,c,v))
w('bidi.bin',[x for r in br for x in r])
JT=['C','D','L','R','T','U']
jr=[]
for l in open(U+'DerivedJoiningType.txt',encoding='utf-8'):
    l=l.split('#')[0].strip()
    if not l: continue
    f=[x.strip() for x in l.split(';')]
    a,b=rng(f[0]); jr.append((a,b,JT.index(f[1])))
jr.sort(); w('joining.bin',[x for r in jr for x in r])
print('bidi ranges',len(br),'joining ranges',len(jr))
tot=0;man={}
for f in sorted(os.listdir(OUT)):
    b=open(OUT+f,'rb').read(); tot+=len(b); man[f]=hashlib.sha256(b).hexdigest()
print('total bytes',tot)
json.dump(man,open('/tmp/idna_manifest.json','w'),indent=1)
